            d["Disk health: back up now!"] = "בריאות הכוננים: לגבות עכשיו!";
            d["Disk health: check"] = "בריאות הכוננים: לבדוק";
            d["Windows reports this drive as unhealthy."] = "Windows מדווח שהכונן הזה לא תקין.";
            d["The drive's own self-check (S.M.A.R.T.) predicts it will fail soon."] = "הבדיקה העצמית של הכונן (S.M.A.R.T.) צופה שהוא ייכשל בקרוב.";
            d["It has used up all of its rated write life (100%)."] = "הכונן ניצל את כל חיי הכתיבה המדורגים שלו (100%).";
            d["Windows reports a warning for this drive."] = "Windows מדווח על אזהרה לכונן הזה.";
            d["Back up now. Copy your important files to another drive or to the cloud today, then plan to replace this drive. Until it is backed up, avoid moving large amounts of data on it."] = "לגבות עכשיו. העתיקו היום את הקבצים החשובים לכונן אחר או לענן, ואז תכננו להחליף את הכונן. עד שהוא מגובה, הימנעו מהעברת כמויות גדולות של נתונים עליו.";
            d["Let the PC cool down: make sure its air vents are free and nothing heavy is running. Check again later."] = "תנו למחשב להתקרר: ודאו שפתחי האוורור פנויים ושלא רץ משהו כבד. בדקו שוב מאוחר יותר.";
            d["Keep a recent backup of anything important and check again in a few days. Replace the drive if the problem grows."] = "שמרו גיבוי עדכני של כל דבר חשוב ובדקו שוב בעוד כמה ימים. החליפו את הכונן אם הבעיה גדלה.";
            d["Nothing to do."] = "אין מה לעשות.";
            d["Windows did not share enough about this drive to judge it."] = "Windows לא סיפק מספיק מידע על הכונן הזה כדי לשפוט את מצבו.";
            d["Wear, temperature and error counts need administrator rights: open Elixar as administrator to see them."] = "שחיקה, טמפרטורה ומספר שגיאות דורשים הרשאות מנהל: פתחו את Elixar כמנהל כדי לראות אותם.";
            d["Windows can't read wear or temperature through this USB connection; that is normal for many USB drives."] = "Windows לא יכול לקרוא שחיקה או טמפרטורה דרך חיבור ה-USB הזה; זה רגיל בהרבה כונני USB.";
            d["This drive doesn't share its wear and temperature with Windows."] = "הכונן הזה לא משתף את נתוני השחיקה והטמפרטורה שלו עם Windows.";
            d["Windows did not report any drives."] = "Windows לא דיווח על אף כונן.";
            d["Your drive looks healthy."] = "הכונן שלכם נראה תקין.";
            d["No problems found, but Windows did not share enough about every drive."] = "לא נמצאו בעיות, אבל Windows לא סיפק מספיק מידע על כל הכוננים.";
            d["Disk health needs Windows."] = "בריאות הכוננים דורשת Windows.";
            d["Windows did not answer in time. Try again in a moment."] = "Windows לא ענה בזמן. נסו שוב בעוד רגע.";
            d["Apply and restart Elixar"] = "החלה והפעלה מחדש של Elixar";
            d["Choose the language and how Elixar looks. To apply a change, Elixar restarts for a moment; nothing else changes."] = "בחרו את השפה ואת המראה של Elixar. כדי להחיל שינוי, Elixar מופעל מחדש לרגע; שום דבר אחר לא משתנה.";
            d["Wait until Elixar finishes, then apply the change."] = "המתינו ש-Elixar יסיים, ואז החילו את השינוי.";
            d["Installing adds Elixar to the Start menu and to Windows' installed apps list (with Uninstall), in a folder only administrators can change. Start Elixar from the Start menu afterwards: Windows no longer shows its blue \"Windows protected your PC\" box for it."] = "ההתקנה מוסיפה את Elixar לתפריט התחל ולרשימת האפליקציות המותקנות של Windows (עם הסרה), בתיקייה שרק מנהלים יכולים לשנות. אחר כך הפעילו את Elixar מתפריט התחל: Windows כבר לא יציג עבורו את החלון הכחול \"Windows protected your PC\".";
            d["Email reports"] = "דוחות במייל";
            d["Sign in with Google"] = "התחברות עם Google";
            d["Set up Google sign-in (one time)..."] = "הגדרת התחברות עם Google (פעם אחת)...";
            d["Send a test email"] = "שליחת מייל בדיקה";
            d["Sign out"] = "התנתקות";
            d["Sign in again"] = "התחברות מחדש";
            d["Cancel sign-in"] = "ביטול ההתחברות";
            d["Save email settings"] = "שמירת הגדרות המייל";
            d["Weekly auto-clean report: what was cleaned, how much it freed, and what is left for you to decide"] = "דוח הניקוי השבועי: מה נוקה, כמה התפנה, ומה נשאר להחלטתך";
            d["Alerts: C: almost full (your limit in Automation, or 15%), or a drive that may fail"] = "התראות: C: כמעט מלא (הגבול שלך באוטומציה, או 15%), או כונן שעלול להיכשל";
            d["Weekly summary every"] = "סיכום שבועי בכל";
            d["(alerts are checked daily at this time too)"] = "(גם ההתראות נבדקות בשעה זו מדי יום)";
            d["Elixar can only send email, never read your inbox. Emails go from your Gmail to you only, list categories and sizes (never your file names), and never contain a link: to delete anything, open Elixar. Your Google sign-in is encrypted on this PC in a folder only administrators can open."] = "Elixar יכול רק לשלוח מיילים, אף פעם לא לקרוא את תיבת הדואר. המיילים נשלחים מה-Gmail שלך אליך בלבד, מציגים קטגוריות וגדלים (אף פעם לא שמות קבצים), ואף פעם לא מכילים קישור: כדי למחוק משהו, פתחו את Elixar. ההתחברות ל-Google מוצפנת במחשב הזה בתיקייה שרק מנהלים יכולים לפתוח.";
            d["Not signed in."] = "לא מחובר.";
            d["Not signed in. Set up Google sign-in once, then sign in."] = "לא מחובר. הגדירו פעם אחת התחברות עם Google, ואז התחברו.";
            d["Waiting for you to sign in to Google in your browser..."] = "ממתין להתחברות ל-Google בדפדפן...";
            d["Finishing sign-in..."] = "מסיים את ההתחברות...";
            d["Sending a test email..."] = "שולח מייל בדיקה...";
            d["Email settings saved."] = "הגדרות המייל נשמרו.";
            d["Sign out of Google? Elixar stops sending emails and Google cancels its permission."] = "להתנתק מ-Google? Elixar יפסיק לשלוח מיילים ו-Google יבטל את ההרשאה.";
            d["Set up Google sign-in"] = "הגדרת התחברות עם Google";
            d["Set up Google sign-in (one time, about 10 minutes)"] = "הגדרת התחברות עם Google (פעם אחת, כ-10 דקות)";
            d["Elixar has no server of its own, so Google needs to know \"Elixar on your PC\" as your own small app. You do this once, in your Google account:"] = "ל-Elixar אין שרת משלו, ולכן Google צריך להכיר את \"Elixar במחשב שלך\" כאפליקציה קטנה משלך. עושים זאת פעם אחת, בחשבון Google שלך:";
            d["1. Open console.cloud.google.com and sign in. Create a project named Elixar."] = "1. פתחו את console.cloud.google.com והתחברו. צרו פרויקט בשם Elixar.";
            d["2. APIs & Services > Library: find \"Gmail API\" and click Enable."] = "2. APIs & Services > Library: חפשו \"Gmail API\" ולחצו Enable.";
            d["3. Google Auth Platform > Get started: app name Elixar, your email, Audience: External."] = "3. Google Auth Platform > Get started: שם האפליקציה Elixar, המייל שלך, Audience: External.";
            d["4. Data access > Add or remove scopes: tick \".../auth/gmail.send\" (send email on your behalf). Nothing else."] = "4. Data access > Add or remove scopes: סמנו \".../auth/gmail.send\" (שליחת מייל בשמך). שום דבר אחר.";
            d["5. Audience > Publish app (In production). Otherwise Google signs Elixar out every 7 days."] = "5. Audience > Publish app (In production). אחרת Google ינתק את Elixar כל 7 ימים.";
            d["6. Clients > Create client > Application type: Desktop app > Create > Download JSON."] = "6. Clients > Create client > Application type: Desktop app > Create > Download JSON.";
            d["7. Click the button below and choose that file."] = "7. לחצו על הכפתור למטה ובחרו את הקובץ הזה.";
            d["When you sign in, Google shows \"Google hasn't verified this app\" because the app is yours and private. Click Advanced > Go to Elixar. Then allow only \"Send email on your behalf\". Elixar can't read your mail."] = "בהתחברות, Google יציג \"Google hasn't verified this app\" כי האפליקציה שלך ופרטית. לחצו Advanced > Go to Elixar. ואז אשרו רק \"Send email on your behalf\". Elixar לא יכול לקרוא את המיילים שלך.";
            d["A Google client is already set up. You can replace it."] = "כבר הוגדר חיבור ל-Google. אפשר להחליף אותו.";
            d["No Google client set up yet."] = "עדיין לא הוגדר חיבור ל-Google.";
            d["Open Google Cloud console"] = "פתיחת Google Cloud console";
            d["Choose the downloaded file..."] = "בחירת הקובץ שהורד...";
            d["Choose the file you downloaded from Google"] = "בחרו את הקובץ שהורדתם מ-Google";
            d["Done. Close this window and click \"Sign in with Google\"."] = "מוכן. סגרו את החלון ולחצו \"התחברות עם Google\".";
            d["No email sent yet."] = "עדיין לא נשלח מייל.";
            d["Email"] = "מייל";
            d["Finds old ads, social notifications, mailing lists, spam and large old emails in your Gmail, and moves the ones you pick to Gmail's Trash. Starred and Important emails are never touched, and Elixar only looks at senders, dates and sizes, never at what your emails say."] = "מוצא פרסומות ישנות, התראות מרשתות חברתיות, רשימות תפוצה, ספאם ומיילים גדולים וישנים ב-Gmail שלך, ומעביר את מה שבחרת לאשפה של Gmail. מיילים מסומנים בכוכב ומיילים חשובים לא נוגעים בהם, ו-Elixar מסתכל רק על שולח, תאריך וגודל, אף פעם לא על תוכן המיילים.";
            d["Emails"] = "מיילים";
            d["About"] = "בערך";
            d["Most from"] = "בעיקר מ-";
            d["Your decision"] = "ההחלטה שלך";
            d["Allow Elixar to check my Gmail..."] = "לאפשר ל-Elixar לבדוק את ה-Gmail שלי...";
            d["Scan my Gmail"] = "סריקת ה-Gmail שלי";
            d["Move selected to Gmail's Trash..."] = "העברת הנבחרים לאשפה של Gmail...";
            d["Turn off Email cleaning..."] = "כיבוי ניקוי המייל...";
            d["Sign in first (Settings)"] = "קודם להתחבר (הגדרות)";
            d["Moved emails stay in Gmail's Trash for 30 days, so you can restore them there. To free the space in your Google account right away, empty the Trash in Gmail."] = "מיילים שהועברו נשארים באשפה של Gmail במשך 30 יום, כך שאפשר לשחזר אותם משם. כדי לפנות את המקום בחשבון Google מיד, רוקנו את האשפה ב-Gmail.";
            d["Not signed in. Sign in with Google in Settings > Email reports first."] = "לא מחובר. קודם התחברו עם Google בהגדרות > דוחות במייל.";
            d["Ads and offers older than a month"] = "פרסומות ומבצעים מלפני יותר מחודש";
            d["Social network notifications older than a month"] = "התראות מרשתות חברתיות מלפני יותר מחודש";
            d["Group and mailing-list emails older than 3 months"] = "מיילים מקבוצות ורשימות תפוצה מלפני יותר מ-3 חודשים";
            d["Spam"] = "ספאם";
            d["Automatic updates older than 6 months"] = "עדכונים אוטומטיים מלפני יותר מחצי שנה";
            d["Large emails (over 10 MB) older than a year"] = "מיילים גדולים (מעל 10 MB) מלפני יותר משנה";
            d["Gmail's Promotions tab: shops, newsletters and deals you have already seen."] = "לשונית קידומי מכירות ב-Gmail: חנויות, ניוזלטרים ומבצעים שכבר ראית.";
            d["Gmail's Social tab: likes, comments and friend requests from Facebook, LinkedIn, Instagram and others."] = "לשונית רשתות חברתיות ב-Gmail: לייקים, תגובות ובקשות חברות מפייסבוק, לינקדאין, אינסטגרם ועוד.";
            d["Gmail's Forums tab: mailing lists and discussion groups."] = "לשונית פורומים ב-Gmail: רשימות תפוצה וקבוצות דיון.";
            d["Gmail removes spam by itself after 30 days; moving it to the Trash just clears it sooner."] = "Gmail מוחק ספאם בעצמו אחרי 30 יום; העברה לאשפה רק מנקה אותו מוקדם יותר.";
            d["Gmail's Updates tab: shipping notices, account alerts, statements and receipts. Check the senders first: you may want to keep receipts."] = "לשונית עדכונים ב-Gmail: הודעות משלוח, התראות חשבון, דפי חשבון וקבלות. בדקו קודם את השולחים: אולי תרצו לשמור קבלות.";
            d["Emails with big attachments, often photos or videos. Your decision: save the attachments first if you need them."] = "מיילים עם קבצים מצורפים גדולים, לרוב תמונות או סרטונים. ההחלטה שלך: שמרו קודם את הקבצים אם צריך.";
            d["Gmail search used:"] = "חיפוש Gmail שבו נעשה שימוש:";
            d["Allow Elixar to check your Gmail?"] = "לאפשר ל-Elixar לבדוק את ה-Gmail שלך?";
            d["To find emails you can clean, Elixar needs Google's permission to see your emails' senders, dates and sizes, and to move emails to Gmail's Trash."] = "כדי למצוא מיילים שאפשר לנקות, Elixar צריך הרשאה מ-Google לראות שולח, תאריך וגודל של המיילים, ולהעביר מיילים לאשפה של Gmail.";
            d["Elixar looks only at senders, dates and sizes. It never opens what your emails say and saves nothing about them."] = "Elixar מסתכל רק על שולח, תאריך וגודל. הוא אף פעם לא פותח את תוכן המיילים ולא שומר עליהם כלום.";
            d["Nothing leaves your PC: Elixar has no server."] = "שום דבר לא יוצא מהמחשב: ל-Elixar אין שרת.";
            d["Emails are only moved to Gmail's Trash, only after you confirm, and can be restored there for 30 days."] = "מיילים רק מועברים לאשפה של Gmail, רק אחרי שאישרת, ואפשר לשחזר אותם משם במשך 30 יום.";
            d["Starred and Important emails are never touched."] = "מיילים מסומנים בכוכב ומיילים חשובים לא נוגעים בהם אף פעם.";
            d["You can turn it off any time on this tab."] = "אפשר לכבות את זה בכל רגע בלשונית הזו.";
            d["Google's own screen will describe this permission in broader words than what Elixar does with it. Continue?"] = "המסך של Google יתאר את ההרשאה במילים רחבות יותר ממה ש-Elixar עושה איתה. להמשיך?";
            d["Turn off Email cleaning?\n\nElixar signs out of Google so the permission to see your emails is taken back. To keep getting email reports, sign in again in Settings (that sign-in can only send)."] = "לכבות את ניקוי המייל?\n\nElixar יתנתק מ-Google כדי לבטל את ההרשאה לראות את המיילים. כדי להמשיך לקבל דוחות במייל, התחברו שוב בהגדרות (ההתחברות הזו יכולה רק לשלוח).";
            d["Google sign-in worked, but the permission to see and tidy your emails wasn't ticked, so Email cleaning stays off."] = "ההתחברות ל-Google הצליחה, אבל ההרשאה לראות ולסדר את המיילים לא סומנה, ולכן ניקוי המייל נשאר כבוי.";
            d["Could not check: "] = "לא הצלחתי לבדוק: ";
            d["Some checks didn't finish: "] = "חלק מהבדיקות לא הסתיימו: ";
            d["Email cleaning: on (Email tab)."] = "ניקוי המייל: פעיל (לשונית מייל).";
            d["Email cleaning: off. Optional: lets Elixar find old ads, notifications and spam in your Gmail."] = "ניקוי המייל: כבוי. אופציונלי: מאפשר ל-Elixar למצוא פרסומות ישנות, התראות וספאם ב-Gmail שלך.";
            d["Turn on Email cleaning..."] = "הפעלת ניקוי המייל...";
            d["Open the Email tab"] = "פתיחת לשונית המייל";
            d["Emails go from your Gmail to you only, list categories and sizes (never your file names), and never contain a link. With Email cleaning on, Elixar can also see your emails' senders, dates and sizes and move emails to Gmail's Trash, only from the Email tab and only after you confirm. Your Google sign-in is encrypted on this PC in a folder only administrators can open."] = "המיילים נשלחים מה-Gmail שלך אליך בלבד, מציגים קטגוריות וגדלים (אף פעם לא שמות קבצים), ואף פעם לא מכילים קישור. כשניקוי המייל פעיל, Elixar יכול גם לראות שולח, תאריך וגודל של המיילים ולהעביר מיילים לאשפה של Gmail, רק מלשונית המייל ורק אחרי שאישרת. ההתחברות ל-Google מוצפנת במחשב הזה בתיקייה שרק מנהלים יכולים לפתוח.";
            d["Email account"] = "חשבון מייל";
            d["Your email:"] = "המייל שלך:";
            d["Outlook / Hotmail / Live"] = "Outlook / Hotmail / Live";
            d["Other (Yahoo, iCloud, AOL, GMX...)"] = "אחר (Yahoo, iCloud, AOL, GMX...)";
            d["Sign in with Microsoft"] = "התחברות עם Microsoft";
            d["Set up Microsoft sign-in (one time)..."] = "הגדרת התחברות עם Microsoft (פעם אחת)...";
            d["Email address"] = "כתובת מייל";
            d["App password"] = "סיסמת אפליקציה";
            d["Incoming (IMAP, port 993)"] = "דואר נכנס (IMAP, פורט 993)";
            d["Outgoing (SMTP, port 587)"] = "דואר יוצא (SMTP, פורט 587)";
            d["Connect"] = "חיבור";
            d["Disconnect"] = "ניתוק";
            d["An app password lets a program open your whole mailbox (that's how email programs work). Elixar keeps it encrypted on this PC in a folder only administrators can open, uses it only for what you turn on here, and always connects securely. You can delete the app password on your provider's site any time."] = "סיסמת אפליקציה מאפשרת לתוכנה לפתוח את כל תיבת הדואר (כך עובדות תוכנות מייל). Elixar שומר אותה מוצפנת במחשב הזה בתיקייה שרק מנהלים יכולים לפתוח, משתמש בה רק למה שהפעלת כאן, ותמיד מתחבר בחיבור מאובטח. אפשר למחוק את סיסמת האפליקציה באתר של ספק המייל בכל רגע.";
            d["Not connected. Choose your email and connect it to get email reports."] = "לא מחובר. בחרו את המייל שלכם וחברו אותו כדי לקבל דוחות במייל.";
            d["Email cleaning: off. Connect your email first."] = "ניקוי המייל: כבוי. קודם חברו את המייל.";
            d["Email cleaning: on. Use the Email tab to scan and clean."] = "ניקוי המייל: פעיל. סריקה וניקוי בלשונית המייל.";
            d["Type your email address: Elixar fills in the servers for well-known providers."] = "הקלידו את כתובת המייל: Elixar ממלא את השרתים לספקים מוכרים.";
            d["Allow Elixar to check your email?"] = "לאפשר ל-Elixar לבדוק את המייל שלך?";
            d["Elixar will use your app password to look at your mailbox and move emails you pick to its Trash."] = "Elixar ישתמש בסיסמת האפליקציה כדי להסתכל בתיבת הדואר ולהעביר לאשפה מיילים שבחרת.";
            d["Emails are only moved to the trash, only after you confirm, and can be restored from there."] = "מיילים רק מועברים לאשפה, רק אחרי שאישרת, ואפשר לשחזר אותם משם.";
            d["Starred, flagged and Important emails are never touched."] = "מיילים מסומנים בכוכב, בדגל או כחשובים לא נוגעים בהם אף פעם.";
            d["You can turn it off any time here in Settings."] = "אפשר לכבות את זה בכל רגע כאן בהגדרות.";
            d["The sign-in screen will describe this permission in broader words than what Elixar does with it."] = "מסך ההתחברות יתאר את ההרשאה במילים רחבות יותר ממה ש-Elixar עושה איתה.";
            d["Continue?"] = "להמשיך?";
            d["Scan my email"] = "סריקת המייל שלי";
            d["Move selected to the trash..."] = "העברת הנבחרים לאשפה...";
            d["Email settings..."] = "הגדרות מייל...";
            d["Turn it on in Settings..."] = "הפעלה בהגדרות...";
            d["Your email isn't connected. Connect it in Settings > Email account, then turn on Email cleaning there."] = "המייל שלך לא מחובר. חברו אותו בהגדרות > חשבון מייל, ואז הפעילו שם את ניקוי המייל.";
            d["Search used:"] = "החיפוש שבו נעשה שימוש:";
            d["Moved emails go to Outlook's Deleted Items, where you can restore them. Empty Deleted Items in Outlook to free the space right away."] = "מיילים שהועברו עוברים לפריטים שנמחקו ב-Outlook, ומשם אפשר לשחזר אותם. רוקנו את הפריטים שנמחקו ב-Outlook כדי לפנות מקום מיד.";
            d["Moved emails go to your mailbox's Trash folder, where you can restore them. Empty the Trash in your email to free the space right away."] = "מיילים שהועברו עוברים לתיקיית האשפה בתיבת הדואר, ומשם אפשר לשחזר אותם. רוקנו את האשפה במייל כדי לפנות מקום מיד.";
            d["Junk Email"] = "דואר זבל";
            d["Spam / Junk folder"] = "תיקיית ספאם / דואר זבל";
            d["Newsletters and ads older than a month"] = "ניוזלטרים ופרסומות מלפני יותר מחודש";
            d["\"Other\" inbox emails older than 2 months"] = "מיילים בתיבת \"אחר\" מלפני יותר מחודשיים";
            d["\"Focused\" inbox emails older than 2 years"] = "מיילים בתיבת \"ממוקד\" מלפני יותר משנתיים";
            d["Outlook's Junk Email folder: messages Outlook already decided are junk."] = "תיקיית דואר הזבל של Outlook: הודעות ש-Outlook כבר קבע שהן זבל.";
            d["Outlook's \"Other\" tab: newsletters, ads and automatic notifications Outlook keeps out of Focused. Flagged and High importance emails are left out."] = "לשונית \"אחר\" ב-Outlook: ניוזלטרים, פרסומות והתראות אוטומטיות ש-Outlook מוציא מ\"ממוקד\". מיילים עם דגל או בחשיבות גבוהה לא נכללים.";
            d["Old emails in your Focused inbox. Your decision: these can be personal. Flagged and High importance emails are left out."] = "מיילים ישנים בתיבת \"ממוקד\". ההחלטה שלך: הם יכולים להיות אישיים. מיילים עם דגל או בחשיבות גבוהה לא נכללים.";
            d["The folder your provider already filled with spam."] = "התיקייה שספק המייל כבר מילא בספאם.";
            d["Emails in your inbox that carry an \"unsubscribe\" link (newsletters, shops, notifications). Flagged emails are left out."] = "מיילים בתיבה עם קישור \"הסרה מרשימת תפוצה\" (ניוזלטרים, חנויות, התראות). מיילים עם דגל לא נכללים.";
            d["Set up Microsoft sign-in"] = "הגדרת התחברות עם Microsoft";
            d["Set up Microsoft sign-in (one time, about 5 minutes)"] = "הגדרת התחברות עם Microsoft (פעם אחת, כ-5 דקות)";
            d["Elixar has no server of its own, so Microsoft needs to know \"Elixar on your PC\" as your own small app. It's free; you do this once:"] = "ל-Elixar אין שרת משלו, ולכן Microsoft צריך להכיר את \"Elixar במחשב שלך\" כאפליקציה קטנה משלך. זה בחינם; עושים זאת פעם אחת:";
            d["Open entra.microsoft.com"] = "פתיחת entra.microsoft.com";
            d["A Microsoft app ID is already set up. You can replace it."] = "כבר הוגדר מזהה אפליקציה של Microsoft. אפשר להחליף אותו.";
            d["No Microsoft app ID set up yet."] = "עדיין לא הוגדר מזהה אפליקציה של Microsoft.";
            d["Done. Close this window and click \"Sign in with Microsoft\"."] = "מוכן. סגרו את החלון ולחצו \"התחברות עם Microsoft\".";
            d["Waiting for you to sign in to Microsoft in your browser..."] = "ממתין להתחברות ל-Microsoft בדפדפן...";
            d["System disk"] = "דיסק המערכת";
            d["Measuring your system disk..."] = "מודד את דיסק המערכת...";
            d["Your system disk is almost full"] = "דיסק המערכת כמעט מלא";
            d["Your system disk is getting full"] = "דיסק המערכת מתמלא";
            d["Your system disk is in good shape"] = "דיסק המערכת במצב טוב";
            d["The safe items are already clean. The Details view shows what else fills the disk."] = "הפריטים הבטוחים כבר נקיים. תצוגת הפרטים מראה מה עוד ממלא את הדיסק.";
            d["What fills the disk"] = "מה ממלא את הדיסק";
            d["Other disks"] = "דיסקים אחרים";
            d["No other disks. A second disk or a USB drive gives you room for big folders."] = "אין דיסקים אחרים. דיסק נוסף או כונן USB נותנים מקום לתיקיות גדולות.";
            d["Your system disk is the only disk. A second disk or a USB drive gives you room for big folders."] = "דיסק המערכת הוא הדיסק היחיד. דיסק נוסף או כונן USB נותנים מקום לתיקיות גדולות.";
            d["Trash"] = "אשפה";
            d["Update packages"] = "חבילות עדכון";
            d["Nothing waiting in the Trash"] = "אין כלום באשפה";
            d["Click to look inside"] = "לחצו כדי להסתכל בפנים";
            d["No downloaded update packages"] = "אין חבילות עדכון שהורדו";
            d["Downloaded update packages, safe to clean"] = "חבילות עדכון שהורדו, בטוח לנקות";
            d["System and apps"] = "המערכת ואפליקציות";
            d["Nothing yet. Cleans and emails show up here."] = "עדיין אין כלום. ניקויים ומיילים יופיעו כאן.";
            d["Browser caches"] = "מטמון דפדפנים";
            d["Developer caches (pip, npm, yarn, Go, Gradle)"] = "מטמון כלי פיתוח (pip, npm, yarn, Go, Gradle)";
            d["Other app caches (~/.cache)"] = "מטמון של אפליקציות אחרות (~/.cache)";
            d["Downloaded update packages (apt)"] = "חבילות עדכון שהורדו (apt)";
            d["Old system logs (journal)"] = "יומני מערכת ישנים (journal)";
            d["Old Snap app versions"] = "גרסאות ישנות של אפליקציות Snap";
            d["Crash reports"] = "דוחות קריסה";
            d["Unused Flatpak runtimes"] = "רכיבי Flatpak שלא בשימוש";
            d["Old kernels and unneeded packages"] = "ליבות ישנות וחבילות מיותרות";
            d["Small pictures of your photos and videos made by the file manager. Rebuilt automatically."] = "תמונות קטנות של התמונות והסרטונים שמנהל הקבצים יוצר. נבנות מחדש אוטומטית.";
            d["Saved copies of websites. Your logins, history and bookmarks are not touched. Sites load a little slower the first time."] = "עותקים שמורים של אתרים. ההתחברויות, ההיסטוריה והסימניות לא נפגעים. אתרים ייטענו קצת לאט יותר בפעם הראשונה.";
            d["Downloaded packages kept by programming tools. They download again when needed."] = "חבילות שכלי תכנות שמרו. הן יורדות שוב כשצריך.";
            d["Everything else apps keep in ~/.cache, which is meant for files they can make again. Close your apps first."] = "כל השאר שאפליקציות שומרות ב-~/.cache, שנועד לקבצים שאפשר ליצור מחדש. סגרו קודם את האפליקציות.";
            d["Files you deleted, waiting in the Trash. Emptying it can't be undone, so look inside first."] = "קבצים שמחקתם, שממתינים באשפה. אי אפשר לבטל ריקון, אז הסתכלו קודם בפנים.";
            d["Package files that updates already installed. Asks for your password once."] = "קובצי חבילות שהעדכונים כבר התקינו. מבקש את הסיסמה שלך פעם אחת.";
            d["Old records of what the system did. The newest 200 MB stay for troubleshooting. Asks for your password once."] = "רישומים ישנים של מה שהמערכת עשתה. 200 ה-MB האחרונים נשארים לפתרון תקלות. מבקש את הסיסמה שלך פעם אחת.";
            d["Snap keeps the previous version of each app for a rollback. The versions in use are not touched. Asks for your password once."] = "Snap שומר את הגרסה הקודמת של כל אפליקציה כדי לחזור אליה. הגרסאות שבשימוש לא נפגעות. מבקש את הסיסמה שלך פעם אחת.";
            d["Reports saved after an app crashed. Only useful if you send them to the developers. Asks for your password once."] = "דוחות שנשמרו אחרי שאפליקציה קרסה. שימושיים רק אם שולחים אותם למפתחים. מבקש את הסיסמה שלך פעם אחת.";
            d["Shared parts no installed Flatpak app needs any more. Asks for your password once."] = "רכיבים משותפים שאף אפליקציית Flatpak מותקנת כבר לא צריכה. מבקש את הסיסמה שלך פעם אחת.";
            d["Older Linux kernels and packages that were installed only for something you removed (\"sudo apt autoremove\"). The running kernel always stays. Asks for your password once."] = "ליבות לינוקס ישנות וחבילות שהותקנו רק בשביל משהו שהסרתם (\"sudo apt autoremove\"). הליבה הפעילה תמיד נשארת. מבקש את הסיסמה שלך פעם אחת.";
            d["These run as systemd timers for your account, even when Elixar is closed. They never run as root, so the system items (which need your password) are left for when you clean yourself."] = "אלה רצים כטיימרים של systemd בחשבון שלך, גם כש-Elixar סגור. הם אף פעם לא רצים כ-root, ולכן פריטי המערכת (שצריכים סיסמה) נשארים לניקוי ידני.";
            d["Warn me when the system disk has less than"] = "הזהר אותי כשבדיסק המערכת יש פחות מ-";
            d["How to install Elixar"] = "איך מתקינים את Elixar";
            d["Fully supported."] = "נתמך במלואו.";
            d["Supported: apt, Snap, Flatpak, the system journal and your caches."] = "נתמך: apt, Snap, Flatpak, יומן המערכת והמטמון שלך.";
