            d["this PC"] = "המחשב הזה";
            d["Your mailbox changed since it was checked. Check it again, then clean."] = "תיבת הדואר השתנתה מאז שנבדקה. בדקו אותה שוב, ואז נקו.";
            d["weekly clean"] = "הניקוי השבועי";
            d["email reports"] = "דוחות המייל";
            d["With Google or Microsoft, Elixar can only send email to you, never read your inbox, until you turn on Email cleaning. Emails list categories and sizes (never your file names) and never contain a link: to delete anything, open Elixar. Your sign-in is encrypted on this PC in a folder only administrators can open."] = "עם Google או Microsoft, Elixar יכול רק לשלוח אליך מיילים, אף פעם לא לקרוא את תיבת הדואר, עד שתפעילו את ניקוי המייל. המיילים מפרטים קטגוריות וגדלים (אף פעם לא שמות של קבצים) ואף פעם לא מכילים קישור: כדי למחוק משהו, פתחו את Elixar. ההתחברות שלך מוצפנת במחשב הזה בתיקייה שרק מנהלים יכולים לפתוח.";
            d["Extra care for Linux. Changes here run fixed commands only, and the system ones ask for your password each time."] = "טיפול נוסף ללינוקס. השינויים כאן מריצים רק פקודות קבועות, ואלה של המערכת מבקשים את הסיסמה שלך בכל פעם.";
            d["kernel"] = "ליבה";
            d["Tools found:"] = "כלים שנמצאו:";
