            d["Clean the build cache"] = "ניקוי מטמון הבנייה";
            d["Remove unused images and stopped containers..."] = "הסרת אימג'ים שלא בשימוש וקונטיינרים שעצרו...";
            d["Volumes, where your databases and app data live, are never touched."] = "ב-Volumes, שבהם נמצאים מסדי הנתונים ונתוני האפליקציות, אף פעם לא נוגעים.";
            d["Docker is not installed."] = "Docker לא מותקן.";
            d["You are not in the docker group, so Elixar can't read the sizes. Cleaning asks for your password."] = "אינך בקבוצת docker, ולכן Elixar לא יכול לקרוא את הגדלים. הניקוי יבקש את הסיסמה שלך.";
            d["Docker is installed but not running."] = "Docker מותקן אבל לא פועל.";
            d["Keep the system logs small"] = "לשמור על יומני המערכת קטנים";
