            d["1 GB"] = "1 GB";
            d["Keep the logs at this size"] = "להגביל את היומנים לגודל הזה";
            d["Remove the limit"] = "הסרת ההגבלה";
            d["A permanent limit: the system itself deletes the oldest logs, so they never grow past it. 500 MB keeps weeks of history for troubleshooting."] = "הגבלה קבועה: המערכת עצמה מוחקת את היומנים הישנים ביותר, כך שהם אף פעם לא עוברים אותה. 500 MB שומרים שבועות של היסטוריה לפתרון בעיות.";
            d["No limit is set (systemd's default: up to a tenth of the disk, at most 4 GB)."] = "לא הוגדרה הגבלה (ברירת המחדל של systemd: עד עשירית מהדיסק, לכל היותר 4 GB).";
            d["This system has no systemd journal."] = "במערכת הזו אין יומן systemd.";
            d["Snap apps"] = "אפליקציות Snap";
            d["Snap is not installed."] = "Snap לא מותקן.";
            d["No Snap apps found."] = "לא נמצאו אפליקציות Snap.";
            d["Versions kept"] = "גרסאות שמורות";
            d["Remove old versions"] = "הסרת גרסאות ישנות";
            d["Snap apps take a lot of space"] = "אפליקציות Snap תופסות הרבה מקום";
            d["There are no old versions to remove."] = "אין גרסאות ישנות להסרה.";
            d["It did not finish:"] = "הפעולה לא הסתיימה:";
            d["Test mode: nothing was changed."] = "מצב בדיקה: שום דבר לא שונה.";
            d["Remove every image no container uses, and every stopped container?\n\nYou download images again when you need them. Volumes (databases, app data) are not touched."] = "להסיר כל אימג' שאף קונטיינר לא משתמש בו, וכל קונטיינר שעצר?\n\nתורידו אימג'ים שוב כשתצטרכו אותם. ב-Volumes (מסדי נתונים, נתוני אפליקציות) לא נוגעים.";
            d["Only on Windows: on Linux, remove apps with the App Center or apt."] = "רק ב-Windows: בלינוקס מסירים אפליקציות עם מרכז האפליקציות או apt.";
            d["Only on Windows for now."] = "בינתיים רק ב-Windows.";
            d["Docker build cache and leftover images"] = "מטמון הבנייה של Docker ואימג'ים שנשארו";
            d["Unused Docker images and stopped containers"] = "אימג'ים של Docker שלא בשימוש וקונטיינרים שעצרו";
            d["What Docker kept from building images, and untagged images left behind (\"docker builder prune\", \"docker image prune\"). Rebuilt when needed. Volumes are never touched. If you are not in the docker group, asks for your password once."] = "מה ש-Docker שמר מבניית אימג'ים, ואימג'ים בלי תג שנשארו (\"docker builder prune\", \"docker image prune\"). נבנים מחדש כשצריך. ב-Volumes אף פעם לא נוגעים. אם אינך בקבוצת docker, תתבקש הסיסמה שלך פעם אחת.";
            d["Images no container uses and containers that are stopped (\"docker image prune -a\", \"docker container prune\"). You download the images again if you need them. Volumes, where your databases and app data live, are never touched. If you are not in the docker group, asks for your password once."] = "אימג'ים שאף קונטיינר לא משתמש בהם וקונטיינרים שעצרו (\"docker image prune -a\", \"docker container prune\"). תורידו את האימג'ים שוב אם תצטרכו. ב-Volumes, שבהם נמצאים מסדי הנתונים ונתוני האפליקציות, אף פעם לא נוגעים. אם אינך בקבוצת docker, תתבקש הסיסמה שלך פעם אחת.";
            d["Elixar can only send email, never read your inbox. Emails go from your Gmail to you only, list categories and sizes (never your file names), and never contain a link: to delete anything, open Elixar. Your Google sign-in is kept on this PC in a folder only your account can open (and encrypted, when your desktop has a keyring)."] = "Elixar יכול רק לשלוח מיילים, אף פעם לא לקרוא את תיבת הדואר. המיילים נשלחים מה-Gmail שלך אליך בלבד, מציגים קטגוריות וגדלים (אף פעם לא שמות קבצים), ואף פעם לא מכילים קישור: כדי למחוק משהו, פתחו את Elixar. ההתחברות ל-Google נשמרת במחשב הזה בתיקייה שרק החשבון שלך יכול לפתוח (ומוצפנת, כשיש בשולחן העבודה מחזיק מפתחות).";
            d["Emails go from your Gmail to you only, list categories and sizes (never your file names), and never contain a link. With Email cleaning on, Elixar can also see your emails' senders, dates and sizes and move emails to Gmail's Trash, only from the Email tab and only after you confirm. Your Google sign-in is kept on this PC in a folder only your account can open (and encrypted, when your desktop has a keyring)."] = "המיילים נשלחים מה-Gmail שלך אליך בלבד, מציגים קטגוריות וגדלים (אף פעם לא שמות קבצים), ואף פעם לא מכילים קישור. כשניקוי המייל פעיל, Elixar יכול גם לראות שולח, תאריך וגודל של המיילים ולהעביר מיילים לאשפה של Gmail, רק מלשונית המייל ורק אחרי שאישרת. ההתחברות ל-Google נשמרת במחשב הזה בתיקייה שרק החשבון שלך יכול לפתוח (ומוצפנת, כשיש בשולחן העבודה מחזיק מפתחות).";
            d["An app password lets a program open your whole mailbox (that's how email programs work). Elixar keeps it on this PC in a folder only your account can open (and encrypted, when your desktop has a keyring), uses it only for what you turn on here, and always connects securely. You can delete the app password on your provider's site any time."] = "סיסמת אפליקציה מאפשרת לתוכנה לפתוח את כל תיבת הדואר (כך עובדות תוכנות מייל). Elixar שומר אותה במחשב הזה בתיקייה שרק החשבון שלך יכול לפתוח (ומוצפנת, כשיש בשולחן העבודה מחזיק מפתחות), משתמש בה רק למה שהפעלת כאן, ותמיד מתחבר בחיבור מאובטח. אפשר למחוק את סיסמת האפליקציה באתר של ספק המייל בכל רגע.";
            d["With Google or Microsoft, Elixar can only send email to you, never read your inbox, until you turn on Email cleaning. Emails list categories and sizes (never your file names) and never contain a link: to delete anything, open Elixar. Your sign-in is kept on this PC in a folder only your account can open (and encrypted, when your desktop has a keyring)."] = "עם Google או Microsoft, Elixar יכול רק לשלוח אליך מיילים, אף פעם לא לקרוא את תיבת הדואר, עד שתפעילו את ניקוי המייל. המיילים מפרטים קטגוריות וגדלים (אף פעם לא שמות של קבצים) ואף פעם לא מכילים קישור: כדי למחוק משהו, פתחו את Elixar. ההתחברות שלך נשמרת במחשב הזה בתיקייה שרק החשבון שלך יכול לפתוח (ומוצפנת, כשיש בשולחן העבודה מחזיק מפתחות).";
            d["Alerts: the system disk is almost full (your limit in Automation, or 15%)"] = "התראות: דיסק המערכת כמעט מלא (הגבול שלך באוטומציה, או 15%)";
            d["Follow the system"] = "לפי המערכת";
            // texts with numbers in them
            Pat(@"Smart scan of (.+?) - (\d+) sets of duplicates \((.+) extra\), (\d+) big files not used for 6 months\.", m => "סריקה חכמה של " + T(m.Groups[1].Value) + ": " + m.Groups[2].Value + " קבוצות כפולים (" + m.Groups[3].Value + " עודפים), " + m.Groups[4].Value + " קבצים גדולים שלא בשימוש 6 חודשים.");
            Pat(@"Smart scan of (.+?) - (Moved .+)", m => "סריקה חכמה של " + T(m.Groups[1].Value) + ": " + T(m.Groups[2].Value));
