            Pat(@"(.+) is a data drive \(no Windows on it\): everything on it is yours to sort\.", m => T(m.Groups[1].Value) + " הוא כונן נתונים (אין עליו Windows): כל מה שעליו שלך למיין.");
            Pat(@"([\d,]+) files read \((.+)\)(, stopped early)?\.", m => m.Groups[1].Value + " קבצים נקראו (" + m.Groups[2].Value + ")" + (m.Groups[3].Success ? ", נעצר מוקדם." : "."));
            Pat(@"(\d+) sets of duplicates: (.+) in extra copies\.", m => m.Groups[1].Value + " קבוצות כפולים: " + m.Groups[2].Value + " בעותקים עודפים.");
            Pat(@"(\d+) files not used lately: (.+)\.", m => m.Groups[1].Value + " קבצים לא בשימוש לאחרונה: " + m.Groups[2].Value + ".");
            Pat(@"(\d+) copies of (.+)  -  (.+) extra", m => m.Groups[1].Value + " עותקים של " + m.Groups[2].Value + "  -  " + m.Groups[3].Value + " עודפים");
            Pat(@"(\d+) selected \((.+)\)", m => m.Groups[1].Value + " נבחרו (" + m.Groups[2].Value + ")");
            Pat(@"Moved (\d+) of (\d+) files \((.+)\) to the Recycle Bin\. Empty the Recycle Bin to free the space\.", m => "הועברו " + m.Groups[1].Value + " מתוך " + m.Groups[2].Value + " קבצים (" + m.Groups[3].Value + ") לסל המיחזור. רוקנו את סל המיחזור כדי לפנות את המקום.");
            Pat(@"Drive ([A-Z]:) - your other drive \(nothing is ticked for you\)", m => "כונן " + m.Groups[1].Value + " - הכונן האחר שלך (שום דבר לא מסומן בשבילך)");
            Pat(@"([A-Z]:) Recycle Bin", m => "סל המיחזור ב-" + m.Groups[1].Value);
            Pat(@"([A-Z]:) disk check leftovers", m => "שאריות בדיקת דיסק ב-" + m.Groups[1].Value);
            Pat(@"([A-Z]:) Steam shader cache", m => "מטמון ה-Shaders של Steam ב-" + m.Groups[1].Value);
            Pat(@"([A-Z]:) unfinished Steam downloads", m => "הורדות Steam שלא הסתיימו ב-" + m.Groups[1].Value);
            Pat(@"Files you deleted from ([A-Z]:), waiting in its Recycle Bin\. Emptying it can't be undone, so look inside first\.", m => "קבצים שמחקת מ-" + m.Groups[1].Value + ", שמחכים בסל המיחזור שלו. אי אפשר לבטל ריקון, אז הסתכלו בפנים קודם.");
            Pat(@"Clean ([A-Z]:) \((.+)\)", m => "ניקוי " + m.Groups[1].Value + " (" + m.Groups[2].Value + ")");
