            Pat(@"Secured the (.+) schedule \(it now starts through Elixar's protected launcher\)\.", m => "התזמון של " + string.Join(" ו", m.Groups[1].Value.Split(new[] { " and " }, StringSplitOptions.None).Select(x => T(x))) + " אובטח (הוא מופעל עכשיו דרך המפעיל המוגן של Elixar).");
            Pat(@"System disk: (.+) free of (.+)", m => "דיסק המערכת: " + m.Groups[1].Value + " פנויים מתוך " + m.Groups[2].Value);
            Pat(@"Images (.+) \((.+) unused\)   ·   containers (.+)   ·   build cache (.+)   ·   volumes (.+) \(kept\)", m => "אימג'ים " + m.Groups[1].Value + " (" + m.Groups[2].Value + " לא בשימוש)   ·   קונטיינרים " + m.Groups[3].Value + "   ·   מטמון בנייה " + m.Groups[4].Value + "   ·   Volumes " + m.Groups[5].Value + " (נשמרים)");
