            Pat(@"Measuring (.+)\.\.\.", m => "מודד את " + m.Groups[1].Value + "...");
            Pat(@"This PC runs (.+)\.", m => "המחשב הזה מריץ " + m.Groups[1].Value + ".");
            Pat(@"(.+) of caches and temp files can be freed safely: your system and apps rebuild them by themselves\.", m => "אפשר לפנות בבטחה " + m.Groups[1].Value + " של מטמון וקבצים זמניים: המערכת והאפליקציות בונות אותם מחדש בעצמן.");
            Pat(@"At this pace your system disk is full around (.+)\.", m => "בקצב הזה דיסק המערכת יתמלא בסביבות " + m.Groups[1].Value + ".");
            Pat(@"Free (.+) safely", m => "פינוי " + m.Groups[1].Value + " בבטחה");
            Pat(@"(.+) free of (.+)\.", m => m.Groups[1].Value + " פנויים מתוך " + m.Groups[2].Value + ".");
            Pat(@"(.+) free of (.+)", m => m.Groups[1].Value + " פנויים מתוך " + m.Groups[2].Value);
            Pat(@"free of (.+)", m => "פנויים מתוך " + m.Groups[1].Value);
            Pat(@"(.+) of caches and temp files can be freed safely: Windows and your apps rebuild them by themselves\.", m => "אפשר לפנות בבטחה " + m.Groups[1].Value + " של מטמון וקבצים זמניים: Windows והאפליקציות בונים אותם מחדש בעצמם.");
            Pat(@"At this pace C: is full around (.+)\.", m => "בקצב הזה C: יתמלא בסביבות " + m.Groups[1].Value + ".");
            Pat(@"Full ~ (.+)", m => "מלא בערך ב-" + m.Groups[1].Value);
            Pat(@"-([\d.]+) GB a month", m => "ירידה של " + m.Groups[1].Value + " GB בחודש");
            Pat(@"\+([\d.]+) GB a month", m => "עלייה של " + m.Groups[1].Value + " GB בחודש");
            Pat(@"(\d+) drives checked", m => m.Groups[1].Value + " כוננים נבדקו");
            Pat(@"(\d+) days ago", m => "לפני " + m.Groups[1].Value + " ימים");
            Pat(@"Freed ([\d.,]+ [KMG]B) \(weekly clean\)", m => "פונו " + m.Groups[1].Value + " (ניקוי שבועי)");
            Pat(@"Freed ([\d.,]+ [KMG]B)", m => "פונו " + m.Groups[1].Value);
            Pat(@"Every (Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)(, with low-space alerts)?", m => "כל יום " + T(m.Groups[1].Value) + (m.Groups[2].Success ? ", עם התראות על מקום נמוך" : ""));
            Pat(@"(\d+) items, kept for 7 days", m => m.Groups[1].Value + " פריטים, נשמרים 7 ימים");
            Pat(@"Email sent: (.+)", m => "נשלח מייל: " + T(m.Groups[1].Value));
            Pat(@"Moved to Undo: (.+) \(([^()]+)\)", m => "הועבר לביטול: " + T(m.Groups[1].Value) + " (" + m.Groups[2].Value + ")");
            Pat(@"Weekly clean freed (.+)", m => "הניקוי השבועי פינה " + m.Groups[1].Value);
            Pat(@"Cleaned (\d+) items, freed (.+)", m => "נוקו " + m.Groups[1].Value + " פריטים, פונו " + m.Groups[2].Value);
            Pat(@"Cleaned (.+), freed (.+)", m => "נוקה " + T(m.Groups[1].Value) + ", פונו " + m.Groups[2].Value);
            Pat(@"Today (\d\d:\d\d)", m => "היום " + m.Groups[1].Value);
            Pat(@"Yesterday (\d\d:\d\d)", m => "אתמול " + m.Groups[1].Value);
            Pat(@"Updated (\d\d:\d\d) \(took (.+)\)\.", m => "עודכן ב-" + m.Groups[1].Value + " (נמשך " + T(m.Groups[2].Value) + ").");
            Pat(@"(\d+) s", m => m.Groups[1].Value + " שנ׳");
            return d;
        }
    }
